INSERT INTO `coa_client_spell_description` (`ID`, `Description`, `ToolTip`) VALUES
(500694, '以神圣能量爆发，对附近敌人造成 ${$803153m1+$803153ppl1+$AP*0.25+$sph*.25} 点神圣伤害，并每 $t3 秒触发一次 |cffffffff狂热|r，持续 $d。@s:801450:0@\r\n\r\n激活时，你的 |cffffffff神殿守护者|r 法术的能量消耗降低 $s1%。', '每 $t3 秒对附近敌人造成 ${$803153m1+$803153ppl1+$AP*0.25+$sph*.25} 点神圣伤害，持续 $d。\r\n\r\n激活时，你的 |cffffffff神殿守护者|r 法术的能量消耗降低。'),
(801832, '对最多 $i 个附近敌人造成 ${$801832m1*$<scalingbp>+$sph*0.25+$AP*0.25} 点神圣伤害。\r\n\r\n必定对亡灵目标造成爆击。', ''),
